	private Vector3 p2StartPos;

	private bool requestRestartConfirmation;

	public static string selectedRoomName = string.Empty;

	private Room selectedRoom;

	private Dictionary<string, GameObject> availableRoomDict;

	private ChaosQuickStopwatch resetSkillStopwatch = new ChaosQuickStopwatch(60f);

	private static readonly string PvpModID = "PVPRoomModID";

	public Light stageLight;

	public AirStageCameraEffects airStageEffects;

	public LightningStageCameraEffects lightStageEffects;

	private bool applyAirRoomBuffs;

	private NumVarStatMod airCDMod = new NumVarStatMod(PvpModID, -0.5f, 10, VarStatModType.Multiplicative);

	private NumVarStatMod airMoveMod = new NumVarStatMod(PvpModID, 0.4f, 10, VarStatModType.Multiplicative);

	private bool applyEarthRoomBuffs;

	private NumVarStatMod earthStunMod = new NumVarStatMod(PvpModID, -0.9f, 10, VarStatModType.Multiplicative);

	private bool applyFireRoomBuffs;

	private NumVarStatMod fireDmgMod = new NumVarStatMod(PvpModID, 1f, 10, VarStatModType.Multiplicative);

	private string droppedSkillID;

	private float empoweredRate = 0.25f;

	private bool forceEmpowerDrop;

	private bool DroppedEmpowered => forceEmpowerDrop || Random.value < empoweredRate;

	private bool BothPlayersReady
	{
		get
		{
			for (int i = 0; i < numberOfPlayers; i++)
			{
				if (!playerReadyCheck[i])
				{
					return false;
				}
			}
			return true;
		}
	}

	private bool BothPlayersAlive
	{
		get
		{
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				if (player.fsm.currentStateName.Contains("Dead"))
				{
					return false;
				}
			}
			return GameController.activePlayers.Length == numberOfPlayers;
		}
	}

	private void Awake()
	{
		winCountTransform = new Transform[2];
		winCountTransform[0] = transform.Find("PvPUI/P1WinCount");
		winCountTransform[1] = transform.Find("PvPUI/P2WinCount");
		winCountTokenPrefab = ChaosBundle.Get("Assets/Prefabs/PvP/WinCountToken.prefab");
		buttonPrompts = transform.Find("PvPUI/ButtonPrompts").gameObject;
				}
				else
				{
					item.Value.SetActive(value: false);
				}
			}
		}
		if (selectedRoom != null)
		{
			StartCoroutine(Pathfinder.GenerateNodeMap(selectedRoom.tileGrid));
			switch (selectedRoom.element)
			{
			case ElementType.Neutral:
				stageLight.intensity = 0.6f;
				break;
			case ElementType.Fire:
				stageLight.intensity = 0.25f;
				break;
			case ElementType.Air:
				stageLight.intensity = 0.55f;
				break;
			case ElementType.Earth:
				stageLight.intensity = 0.55f;
				break;
			case ElementType.Lightning:
				stageLight.intensity = 0.35f;
				break;
			case ElementType.Water:
				stageLight.intensity = 0.3f;
				break;
			default:
				stageLight.intensity = 0.4f;
				break;
			}
		}
	}

	private void Update()
	{
		if (!playersReady)
		{
			TogglePlayerInvulnerable(status: true);
			if (BothPlayersAlive && (BothPlayersReady || matchInProgress))
			{
				ResetPlayers(fullReset: true);
				playersReady = true;
			if (player.fsm.currentStateName.Contains("Fall"))
			{
				if (!playerFallCheck[player.playerID])
				{
					player.lastCheckpoint = respawnLocations[Random.Range(0, respawnLocations.Count)];
					player.fall.preFallPos = player.lastCheckpoint;
					playerFallCheck[player.playerID] = true;
				}
			}
			else if (playerFallCheck[player.playerID])
			{
				playerFallCheck[player.playerID] = false;
			}
		}
	}
	private void HandleSkillSpawn()
	{
		if (!resetSkillStopwatch.IsRunning)
		{
			resetSkillStopwatch.IsRunning = true;
			LootManager.ResetAvailableSkills();
		}
		if (ChaosStopwatch.Check(skillSpawnStopwatchID))
		{
			skillSpawnStopwatchID = ChaosStopwatch.Begin(skillSpawnTime + Random.Range(-1f, 1f));
			droppedSkillID = LootManager.GetSkillID();
			if (!(droppedSkillID == string.Empty))
			{
				skillSpawnLocIndex = (skillSpawnLocIndex + Random.Range(1, skillSpawnLocCount)) % skillSpawnLocCount;
				Vector3 vector = skillSpawnLocations[skillSpawnLocIndex];
				Vector3 spawnLocation = vector;
				int amount = 1;
				string skillID = droppedSkillID;
				bool droppedEmpowered = DroppedEmpowered;
				LootManager.DropSkill(spawnLocation, amount, skillID, 0f, 0f, null, useLifeTime: true, droppedEmpowered);
				vector.y -= 0.5f;
				Player.SpawnAllyPortal(vector, 0.5f);
			}
		}
	}
	private void ApplyAirBuffs()
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (!(player == null))
			{
				StatManager.ModifyAllStatData(airCDMod, player.skillCategory, "cooldown");
				player.movement.moveSpeedStat.Modify(airMoveMod, addMod: true);
			}
		}
	}
	private void ApplyEarthBuffs()
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (player != null)
			{
				player.health.hitStunModifierStat.Modify(earthStunMod, addMod: true);
			}
		}
	}
	private void ApplyFireBuffs()
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (player != null)
			{
				player.health.damageTakenStat.Modify(fireDmgMod, addMod: true);
			}
		}
	}
	private void TogglePlayerInvulnerable(bool status)
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			player.health.invulnerable = status;
		}
	}
	private void ResetPlayers(bool fullReset = false)
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			player.myOrigin = ((player.playerID != 0) ? p2StartPos : p1StartPos);
			player.lastCheckpoint = player.myOrigin;
			player.ResetPlayer(originPosition: true, fullyRestoreHealth: true, resetState: true, fullReset);
			Player.SpawnAllyPortal(player.transform.position);
			List<GameObject> list = new List<GameObject>();
			player.CleanUpPlayerSummonsList();
			foreach (GameObject playerSummons in player.playerSummonsList)
			{
				if (playerSummons != null && playerSummons != player.gameObject)
				{
					list.Add(playerSummons);
				}
			}
			foreach (GameObject item in list)
			{
				Entity component = item.GetComponent<Entity>();
				if (component != null && component.fsm.HasState("Dead"))
				{
					component.fsm.ChangeState("Dead");
				}
				Ward component2 = item.GetComponent<Ward>();
				if (component2 != null)
				{
					component2.DestroyWard();
				}
			}
			list.Clear();
			player.CleanUpPlayerSummonsList();
		}
	}
	private void ResetStage(bool fullReset = false)
	{
		GameUI.BroadcastNoticeMessage(" ");
		if (fullReset)
		{
			for (int i = 0; i < numberOfPlayers; i++)
			{
				playerWinCounts[i] = 0;
			}
			Transform[] array = winCountTransform;
			foreach (Transform transform in array)
			{
				Transform[] componentsInChildren = transform.GetComponentsInChildren<Transform>();
				foreach (Transform transform2 in componentsInChildren)
