using System.Collections.Generic;
using System.Linq;
using UnityEngine;
public static class StatManager
{
	public delegate bool ModApplyConditional(StatData givenStatData);
	private static readonly string statFieldStr = "Skills";
	private static readonly string playerSkillAssetPath = "Assets/Data/Player/Skills.json";
	private static readonly string playerBaseCategory = "Player";
	private static readonly string enemySkillAssetPath = "Assets/Data/Enemy/Skills.json";
	public static readonly string enemyBaseCategory = "Enemy";
	public static Dictionary<string, StatData> globalSkillData = new Dictionary<string, StatData>();
	public static Dictionary<string, Dictionary<string, Dictionary<string, StatData>>> data = new Dictionary<string, Dictionary<string, Dictionary<string, StatData>>>();
	private static List<StatData> modifiedStatDataList;
	private static StatData modifiedStatData;
	public static void LoadPlayerSkills(string categoryModifier = "")
	{
		LoadData(playerSkillAssetPath, statFieldStr, playerBaseCategory, categoryModifier);
	}
	public static void LoadEnemySkills(string categoryModifier = "")
	{
		LoadData(enemySkillAssetPath, statFieldStr, enemyBaseCategory, categoryModifier);
	}
	public static void LoadData(string assetPath, string statID, string category, string categoryModifier = "")
	{
		string text = category + categoryModifier;
		if (!data.ContainsKey(statID))
		{
			data[statID] = new Dictionary<string, Dictionary<string, StatData>>();
		}
		data[statID][text] = new Dictionary<string, StatData>();
		Dictionary<string, StatData> dictionary = data[statID][text];
		SkillStatContainer skillStatContainer = JsonUtility.FromJson<SkillStatContainer>(ChaosBundle.Get<TextAsset>(assetPath).text);
		int num = skillStatContainer.skillStats.Length;
		bool flag = category == "Enemy";
		for (int i = 0; i < num; i++)
		{
			skillStatContainer.skillStats[i].Initialize();
			StatData statData = new StatData(skillStatContainer.skillStats[i], text);
			List<string> value = statData.GetValue<List<string>>("targetNames");
			if (value.Contains(Globals.allyHBStr) || value.Contains(Globals.enemyHBStr))
			{
				value.Add(Globals.ffaHBStr);
			}
			if (value.Contains(Globals.allyFCStr) || value.Contains(Globals.enemyFCStr))
			{
				value.Add(Globals.ffaFCStr);
			}
			if (flag)
			{
				switch (categoryModifier)
				{
				case "Only":
					if (value.Contains(Globals.allyHBStr))
					{
						value.Remove(Globals.allyHBStr);
						value.Add(Globals.enemyHBStr);
					}
					if (value.Contains(Globals.allyFCStr))
					{
						value.Remove(Globals.allyFCStr);
						value.Add(Globals.enemyFCStr);
					}
					break;
				case "FFA":
					if (value.Contains(Globals.allyHBStr))
					{
						value.Add(Globals.enemyHBStr);
					}
					if (value.Contains(Globals.allyFCStr))
					{
						value.Add(Globals.enemyFCStr);
					}
					break;
				case "AsAlly":
					value.Remove(Globals.ffaHBStr);
					value.Remove(Globals.ffaFCStr);
					break;
				}
				statData.currentLevel = 1;
			}
			dictionary[statData.GetValue<string>("ID")] = statData;
			globalSkillData[statData.GetValue<string>("ID")] = statData;
		}
	}
	public static StatData GetSkillData(string category, string skillID)
	{
		return GetStatData("Skills", category, skillID);
	}
	public static StatData GetStatData(string statID, string category, string skillID)
	{
		if (!data.ContainsKey(statID) || !data[statID].ContainsKey(category))
		{
			return null;
		}
		if (!data[statID][category].ContainsKey(skillID))
		{
			return (!globalSkillData.ContainsKey(skillID)) ? null : globalSkillData[skillID];
		}
		return data[statID][category][skillID];
	}
	public static List<StatData> GetAllStatData(string statID, string fullCategoryStr)
	{
		return data[statID][fullCategoryStr].Values.ToList();
	}
	public static void ModifyAllStatData(NumVarStatMod givenMod, string givenCategory, string statFieldStr, ModApplyConditional GivenConditional = null, bool addMod = true)
	{
		modifiedStatDataList = GetAllStatData("Skills", givenCategory);
		if (addMod)
		{
			for (int num = modifiedStatDataList.Count - 1; num > -1; num--)
			{
				modifiedStatData = modifiedStatDataList[num];
				if (GivenConditional == null || GivenConditional(modifiedStatData))
				{
					modifiedStatData.AddMod(statFieldStr, givenMod);
				}
			}
		}
		else
		{
			for (int num2 = modifiedStatDataList.Count - 1; num2 > -1; num2--)
			{
				modifiedStatData = modifiedStatDataList[num2];
				if (GivenConditional == null || GivenConditional(modifiedStatData))
				{
					modifiedStatData.RemoveMod(statFieldStr, givenMod.ID);
				}
			}
		}
		modifiedStatDataList.Clear();
		modifiedStatData = null;
	}
	public static void ModifyAllStatData(Dictionary<string, NumVarStatMod> givenDict, string givenCategory, ModApplyConditional GivenConditional = null, bool addMod = true)
	{
		if (givenDict == null)
		{
			return;
		}
		modifiedStatDataList = GetAllStatData("Skills", givenCategory);
		if (addMod)
		{
			for (int num = modifiedStatDataList.Count - 1; num > -1; num--)
			{
				modifiedStatData = modifiedStatDataList[num];
				if (GivenConditional == null || GivenConditional(modifiedStatData))
				{
					foreach (KeyValuePair<string, NumVarStatMod> item in givenDict)
					{
						modifiedStatData.AddMod(item.Key, item.Value);
					}
				}
			}
		}
		else
		{
			for (int num2 = modifiedStatDataList.Count - 1; num2 > -1; num2--)
			{
				modifiedStatData = modifiedStatDataList[num2];
				if (GivenConditional == null || GivenConditional(modifiedStatData))
				{
					foreach (KeyValuePair<string, NumVarStatMod> item2 in givenDict)
					{
						modifiedStatData.RemoveMod(item2.Key, item2.Value.ID);
					}
				}
			}
		}
		modifiedStatDataList.Clear();
		modifiedStatData = null;
	}
}

