using System.Collections.Generic;
public class CritChanceDownDamageUp : Item
{
	public static string staticID = "CritChanceDownDamageUp";
	private Dictionary<string, NumVarStatMod> modDict;
	protected override string ExtraInfo => PercentToStr(1f, "+") + " | " + PercentToStr(0.25f, "-");
	public CritChanceDownDamageUp()
	{
		ID = staticID;
		category = Category.Offense;
		isCursed = true;
		modDict = new Dictionary<string, NumVarStatMod>
		{
			{
				StatData.critChStr,
				new NumVarStatMod(ID, -0.25f)
			},
			{
				StatData.critDmgStr,
				new NumVarStatMod(ID, 1f)
			}
		};
	}
	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}
	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}
	public virtual void SetModStatus(bool givenStatus)
	{
		StatManager.ModifyAllStatData(modDict, parentSkillCategory, IgnoreStatusConditional, givenStatus);
	}
}
