== ElementalResistanceUp
public class ElementalResistanceUp : Item
{
	private ElementType element;
	private NumVarStatMod resistMod;
	protected override string ExtraInfo => PercentToStr(resistMod, "+");
	public ElementalResistanceUp(string givenID, ElementType givenElement)
	{
		ID = givenID;
		category = Category.Defense;
		parentGroupID = ResistanceUpGroupItem.staticID;
		element = givenElement;
		resistMod = new NumVarStatMod(ID, -0.25f, 10, VarStatModType.Multiplicative);
	}
	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}
	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}
	private void SetModStatus(bool givenStatus)
	{
		if ((!givenStatus || !GroupItemCreated(ResistanceUpGroupItem.staticID)) && parentEntity != null && parentEntity.health != null)
		{
			parentEntity.health.elemModDict[element].Modify(resistMod, givenStatus);
			parentEntity.health.statusResDict[element].Modify(resistMod, givenStatus);
		}
	}
}
